import itertools
import time
start = time.time()

n = 23
fixed = {5: -1, 10: -1, 13: 1, 19: 1}
fixed_c = {12: 0, 13: -3, 16: 0, 19: -1}
free_pos = [i for i in range(n) if i not in fixed]

found = False
solution = None
min_merit = float('inf')

for bits in itertools.product([-1,1], repeat=len(free_pos)):
    seq = [0]*n
    for i, pos in enumerate(free_pos):
        seq[pos] = bits[i]
    for pos, val in fixed.items():
        seq[pos] = val

    # compute C_k
    C = [0] * n
    for k in range(1, n):
        for i in range(n - k):
            C[k] += seq[i] * seq[i + k]

    # check fixed C
    match = True
    for k, val in fixed_c.items():
        if C[k] != val:
            match = False
            break
    if not match:
        continue

    merit = sum(c*c for c in C[1:])
    if merit < min_merit:
        min_merit = merit
    if merit <= 59:
        found = True
        solution = seq
        break

print("Time taken:", time.time() - start)
print("Found:", found)
if found:
    print("Solution:", solution)
    print("Merit:", merit)
print("Min merit found:", min_merit)
